test('Inbox sign-in asks Chatwoot with GET and keeps the platform token off the page',async()=>{const vm=require('vm');let method='',requested='';const sandbox={module:{exports:{}},exports:{},URL,AbortSignal,require:n=>n==='./reach'?{}:n==='@nestjs/common'?{BadRequestException:Error}:n==='pg'?{Client:class{}}:{},process:{env:{CHATWOOT_API_URL:'https://inbox.intelli-verse-x.ai',CHATWOOT_PLATFORM_TOKEN:'fixture-token'}},fetch:async(_url,o)=>{method=o.method;requested=String(_url);return {ok:true,json:async()=>({url:'https://inbox.intelli-verse-x.ai/app/login?email=a&sso_auth_token=once'})};}};sandbox.module.exports=sandbox.exports;vm.runInNewContext(fs.readFileSync(__dirname+'/hired-desk-queues.js','utf8'),sandbox);const result=await sandbox.exports.inboxLogin('Kiosk X',sandbox.process.env,sandbox.fetch);assert.equal(method,'GET');assert.ok(result.url.includes('sso_account_id=1'));assert.ok(result.url.includes('sso_auth_token=once'));assert.ok(!result.url.includes('fixture-token'));assert.ok(!fs.readFileSync(__dirname+'/kioskx-desk-queues.js','utf8').includes('CHATWOOT_PLATFORM_TOKEN'));for(const [company,account,id] of [['AniDeeBee',1,3],['Kiosk X',1,101],['ToBa Tech',34,36],['QuizVerse',1,2],['QuestX',1,103],['ContentX Studio',1,102],['IntelliVerse X',1,100]]){const r=await sandbox.exports.inboxLogin(company,sandbox.process.env,sandbox.fetch);assert.equal(method,'GET');assert.equal(new URL(requested).pathname,'/platform/api/v1/users/1/login');assert.equal(new URL(r.url).searchParams.get('sso_account_id'),String(account));assert.equal(new URL(r.url).searchParams.has('sso_conversation_id'),false);assert.equal(r.inbox,`https://inbox.intelli-verse-x.ai/app/accounts/${account}/inbox/${id}`);assert.ok(!JSON.stringify(r).includes('fixture-token'));}});

