async function calendarCompany(m,company='AniDeeBee'){const select=m.d.querySelector('[aria-label=Company]');select.value=company;select.dispatchEvent(new m.w.Event('change'));button(m.d,'Calendar').click();await pause();}
test('Disabled Calendar API renders the exact sentence and no event chip',async()=>{const {list}=require('./desk-calendar');const response=await list({company:'AniDeeBee',month:'2026-11'},{env:{DESK_CALENDAR_ID:'support@anideebee.com',DESK_CALENDAR_REFRESH_TOKEN:'disabled-fixture'},request:async url=>({ok:!url.includes('/calendar/'),json:async()=>url.includes('/calendar/')?{error:{details:[{reason:'SERVICE_DISABLED'}]}}:{access_token:'fixture'}})});const m=await mount({calendar:()=>response});try{await calendarCompany(m);assert.equal(m.d.querySelector('.sd-calendar-status').textContent,'Google Calendar API is turned off for support@anideebee.com.');assert.equal(m.d.querySelectorAll('.sd-calendar-event').length,0);assert.ok(m.d.querySelector('.sd-calendar-grid'));assert.equal(m.d.querySelector('.sd-calendar-connect'),null);assert.ok(!m.d.querySelector('.sd-page-calendar').textContent.includes('Calendar not connected'));}finally{m.close();}});
test('Fixture event lands on its day with title and time; navigation and 20 second refresh preserve month',async()=>{const timer={ms:20000};const m=await mount({timer,calendar:url=>{const month=new URL(url,'https://fixture.invalid').searchParams.get('month');return {connected:true,events:[{id:'fixture',title:'Fixture appointment',start:month+'-12T10:30:00',end:month+'-12T11:00:00'}]};}});try{await calendarCompany(m);const today=new Date(),month=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0');assert.ok(m.d.querySelector(`[data-date="${month}-12"] .sd-calendar-event`).textContent.includes('Fixture appointment'));assert.ok(m.d.querySelector('.sd-calendar-event time').textContent.includes('10:30'));assert.equal(m.d.querySelectorAll('.sd-calendar-event').length,1);assert.ok(m.d.querySelector('[aria-current=date]'));button(m.d,'Next month').click();await pause();const next=m.calls.filter(c=>c.url.includes('/calendar?')).at(-1).url;assert.ok(!next.endsWith(month));const label=m.d.querySelector('.sd-calendar-toolbar h2').textContent;await timer.tick();await pause();assert.equal(m.calls.filter(c=>c.url.includes('/calendar?')).at(-1).url,next);assert.equal(m.d.querySelector('.sd-calendar-toolbar h2').textContent,label);button(m.d,'Previous month').click();await pause();assert.ok(m.calls.filter(c=>c.url.includes('/calendar?')).at(-1).url.endsWith(month));button(m.d,'Today').click();await pause();assert.ok(m.d.querySelector('[aria-current=date]'));assert.equal(m.calls.filter(c=>c.method==='POST').length,0);}finally{m.close();}});
test('A company without a token gets one Connect calendar button and no grid or AniDeeBee events',async()=>{const m=await mount();try{for(const company of ['Kiosk X','ToBa Tech','AniDeeBee']){await calendarCompany(m,company);const page=m.d.querySelector('.sd-page-calendar');assert.equal(page.querySelectorAll('button').length,1);assert.equal(page.querySelector('button').textContent,'Connect calendar');assert.equal(page.querySelector('.sd-calendar-grid'),null);assert.equal(page.querySelector('.sd-calendar-event'),null);page.querySelector('button').click();assert.ok(page.textContent.includes('Ask your administrator'));}assert.equal(m.calls.filter(c=>c.method==='POST').length,0);}finally{m.close();}});
test('Switching companies discards a late AniDeeBee calendar response',async()=>{let resolve;const m=await mount({calendar:url=>url.includes('AniDeeBee')?new Promise(r=>resolve=r):{connected:false}});try{await calendarCompany(m);await calendarCompany(m,'Kiosk X');resolve({connected:true,events:[{title:'Private appointment',start:new Date().toISOString(),end:new Date(Date.now()+3600000).toISOString()}]});await pause();assert.equal(m.d.querySelector('.sd-calendar-event'),null);assert.equal(m.d.querySelector('.sd-calendar-grid'),null);assert.ok(!m.d.querySelector('.sd-page-calendar').textContent.includes('Private appointment'));}finally{m.close();}});
test('Manager adds, edits, and deletes an event without a guest or a Google consent screen',async()=>{const m=await mount({calendar:()=>({connected:true,events:[{id:'evt_1',title:'Fixture appointment',start:'2026-11-18T16:00:00.000Z',end:'2026-11-18T16:30:00.000Z'}]})});try{await calendarCompany(m);const page=m.d.querySelector('.sd-page-calendar');assert.equal(page.querySelector('[aria-label="Event title"]').value,'');assert.equal(page.querySelector('a'),null);page.querySelector('[aria-label="Event title"]').value='Desk visit';page.querySelector('[aria-label="Event date"]').value='2026-11-18';page.querySelector('[aria-label="Start time"]').value='10:00';page.querySelector('[aria-label="End time"]').value='10:30';button(m.d,'Add event').click();await pause();const created=m.calls.find(c=>c.method==='POST'&&String(c.url).endsWith('/calendar'));const body=JSON.parse(created.body);assert.equal(body.action,'create');assert.equal(body.company,'AniDeeBee');assert.equal(body.title,'Desk visit');assert.equal(body.attendees,undefined);assert.ok(!created.body.includes('@'));button(m.d,'Edit').click();await pause();assert.equal(page.querySelector('[aria-label="Event title"]').value,'Fixture appointment');button(m.d,'Delete event').click();await pause();const removed=m.calls.filter(c=>c.method==='POST').at(-1);assert.equal(JSON.parse(removed.body).action,'delete');assert.equal(JSON.parse(removed.body).id,'evt_1');assert.ok(!removed.body.includes('@'));}finally{m.close();}});
test('A signed-out calendar says to sign in on the support desk',async()=>{const m=await mount({calendar:()=>({httpStatus:403})});try{await calendarCompany(m);assert.equal(m.d.querySelector('.sd-calendar-status').textContent,'Sign in on the support desk to manage this calendar.');assert.ok(button(m.d,'Retry'));assert.equal(m.d.querySelector('.sd-calendar-form'),null);}finally{m.close();}});

test('AniDeeBee exposes all paths before typing; reading only posts company-site and shows summary',async()=>{
 const m=await mount();try{choose(m,'AniDeeBee');button(m.d,'Engagement').click();await pause();const page=m.d.querySelector('.sd-page-engagement');
 for(const copy of ['Saves this lead to AniDeeBee in the CRM. No email or text is sent.','Mail Studio has no templates for this company.','Texts are for US and Canada numbers with consent. India numbers are blocked.','Gojiberry is not provisioned for AniDeeBee.'])assert.ok(page.textContent.includes(copy));
 const read=button(m.d,'Read their site');assert.equal(read.hidden,false);assert.equal(read.disabled,true);assert.equal(button(m.d,'Send email').disabled,true);assert.equal(button(m.d,'Send text').disabled,true);
 const url=page.querySelector('[aria-label="Lead website"]');url.value='https://example.invalid';url.dispatchEvent(new m.w.Event('input'));assert.equal(m.calls.filter(c=>c.method==='POST').length,0);read.click();await pause();
 const posts=m.calls.filter(c=>c.method==='POST');assert.equal(posts.length,1);assert.ok(posts[0].url.endsWith('/company-site'));assert.match(page.textContent,/A public page summary/);assert.doesNotMatch(page.textContent,/Enter a public page to read|https?:\/\/\S*webhook/i);
 }finally{m.close();}
});
test('CRM requires valid email and its own click, submits kind lead once and confirms no email',async()=>{
 const m=await mount();try{choose(m,'AniDeeBee');button(m.d,'Engagement').click();await pause();const send=button(m.d,'Save lead to CRM — no email'),email=m.d.querySelector('[aria-label="Email"]');assert.equal(send.disabled,true);email.value='invalid';email.dispatchEvent(new m.w.Event('input'));send.click();assert.equal(m.calls.filter(c=>c.method==='POST').length,0);email.value='lead@example.invalid';email.dispatchEvent(new m.w.Event('input'));assert.equal(m.calls.filter(c=>c.method==='POST').length,0);send.click();send.click();await pause();const posts=m.calls.filter(c=>c.method==='POST');assert.equal(posts.length,1);assert.ok(posts[0].url.endsWith('/company-send'));assert.equal(JSON.parse(posts[0].body).kind,'lead');assert.equal(JSON.parse(posts[0].body).emailConsent,false);assert.match(m.d.querySelector('.sd-page-engagement').textContent,/No email was sent/);
 }finally{m.close();}
});
test('Company switch clears summary, inputs and deliveries immediately and ignores late reads',async()=>{
 let finish;const m=await mount({site:()=>new Promise(r=>finish=r)});try{choose(m,'AniDeeBee');button(m.d,'Engagement').click();await pause();m.d.querySelector('[aria-label="Email"]').value='old@example.invalid';const url=m.d.querySelector('[aria-label="Lead website"]');url.value='https://example.invalid';url.dispatchEvent(new m.w.Event('input'));button(m.d,'Read their site').click();choose(m,'Kiosk X');assert.doesNotMatch(m.d.querySelector('.sd-page-engagement').textContent,/AniDeeBee|Reading this page/);assert.equal(m.d.querySelector('[aria-label="Email"]'),null);finish({ok:true,json:async()=>({summary:'Old private summary'})});await pause();const page=m.d.querySelector('.sd-page-engagement');assert.match(page.textContent,/Email sends from support@kiosk-x.ai\./);assert.doesNotMatch(page.textContent,/AniDeeBee|Old private summary/);assert.equal(page.querySelector('[aria-label="Email"]').value,'');assert.ok(page.querySelector('tbody tr'));choose(m,'AniDeeBee');assert.equal(m.d.querySelector('.sd-page-engagement tbody'),null);await pause();assert.equal(m.d.querySelector('.sd-page-engagement tbody'),null);
 }finally{m.close();}
});
test('Disconnected tools remain visible and disabled; failed engagement offers refresh',async()=>{
 const m=await mount({engagement:async()=>({ok:true,json:async()=>({site:false,lead:false,sms:false,mail:{templates:[],message:'Mail Studio has no templates for this company.'}})})});try{button(m.d,'Engagement').click();await pause();for(const label of ['Read their site','Save lead to CRM — no email','Send email','Send text'])assert.equal(button(m.d,label).disabled,true);for(const copy of ['Site reading is not connected.','CRM save is not connected for this company.','Text sending is unavailable.','Router admin contract is not configured.'])assert.ok(m.d.querySelector('.sd-page-engagement').textContent.includes(copy));assert.equal(m.calls.filter(c=>c.method==='POST').length,0);}finally{m.close();}
 const n=await mount({engagement:async()=>{throw Error();}});try{button(n.d,'Engagement').click();await pause();assert.match(n.d.querySelector('.sd-page-engagement').textContent,/Company tools are unavailable. Try refreshing./);}finally{n.close();}
});
test('Unreadable site response shows failure and never saves or sends',async()=>{
 const m=await mount({site:async()=>({ok:true,json:async()=>({unavailable:true})})});try{button(m.d,'Engagement').click();await pause();const url=m.d.querySelector('[aria-label="Lead website"]');url.value='http://127.0.0.1';url.dispatchEvent(new m.w.Event('input'));button(m.d,'Read their site').click();await pause();assert.match(m.d.querySelector('.sd-page-engagement').textContent,/This site could not be read\./);assert.equal(m.calls.filter(c=>c.method==='POST').length,1);assert.equal(m.calls.filter(c=>c.url.includes('company-send')).length,0);}finally{m.close();}
});
